int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> a;
    a.reserve(n + 2);
    a.push_back(0); // sentinela na esquerda
    for (int i = 0; i < n; ++i) {
        int x;
        cin >> x;
        if (a.empty() || a.back() != x) {
            a.push_back(x);
        }
    }
    a.push_back(0); // sentinela na direita

    int m = a.size() - 2;
    if (m <= 0) {
        cout << 1 << "\n";
        return 0;
    }

    // Criar lista de posições e ordenar por altura decrescente
    vector<pair<int, int>> elements;
    elements.reserve(m);
    for (int i = 1; i <= m; ++i) {
        elements.push_back({a[i], i});
    }

    sort(elements.begin(), elements.end(), [](const pair<int, int>& p1, const pair<int, int>& p2) {
        return p1.first > p2.first;
    });

    vector<bool> active(m + 2, false);
    int current_components = 0;
    int max_pieces = 1;

    int total_elements = elements.size();
    for (int i = 0; i < total_elements; ) {
        int j = i;
        // Processa todos os elementos com a mesma altura
        while (j < total_elements && elements[j].first == elements[i].first) {
            int pos = elements[j].second;
            active[pos] = true;

            bool left_active = active[pos - 1];
            bool right_active = active[pos + 1];

            if (!left_active && !right_active) {
                current_components++;
            } else if (left_active && right_active) {
                current_components--;
            }
            j++;
        }

        // Um corte horizontal logo abaixo desta altura gera 1 pedaço na base + current_components no topo
        max_pieces = max(max_pieces, 1 + current_components);

        i = j;
    }

    cout << max_pieces << "\n";

    return 0;
}
